<script lang="ts">
  import { onMount } from 'svelte';
  import { Button, Badge } from '@swal/ui';
  import AppShell from '../lib/shell/AppShell.svelte';
  import ExerciseArt from './ExerciseArt.svelte';
  import { initializeLocalStorage } from '../lib/localStorageAdapter';
  import { readLocal, saveLocal } from '../lib/repository';
  import { exercises,searchExercises,exerciseByRef,starterRoutines,target,ulid,startSession,logSet,finishSession,sessionVolume,progress,weeklyVolume,toHealthFile,parseHealthFile,orionDeepLink,kgToDisplay,displayToKg, type Preferences,type Routine,type ActiveSession,type Workout,type DietaryProfile,type Target } from '../lib/training';
  import type { IconName } from '../lib/shell/icons';
  let { page='library',slug='' }:{page?:string;slug?:string}=$props();
  let ready=$state(false), error=$state(''), message=$state(''), busy=$state(false);
  let prefs=$state<Preferences>({theme:'system',units:'kg',language:'es',bodyKg:70,subject:''});
  let routines=$state<Routine[]>([]), sessions=$state<Workout[]>([]), active=$state<ActiveSession|null>(null), profile=$state<DietaryProfile|null>(null);
  let query=$state(''), muscle=$state(''), equipment=$state(''), type=$state(''), visible=$state(24);
  let editing=$state<Routine|null>(null), addRef=$state(exercises[0].id), routineQuery=$state('');
  let reps=$state(10),weight=$state(0),duration=$state(45),distance=$state(400),notes=$state(''),effort=$state(7),clock=$state(Date.now()),link=$state(''),importText=$state('');
  let pendingProfile=$state<DietaryProfile|null>(null);
  let pendingRestore=$state<Workout[]|null>(null);
  let progressRef=$state(exercises[0].id);
  const englishErrors:Record<string,string>={'Ejercicio desconocido':'Unknown exercise','Valores de serie inválidos':'Invalid set values','Introduce repeticiones':'Enter reps','Introduce duración':'Enter duration','Introduce distancia':'Enter distance','Introduce peso':'Enter weight','Registra al menos una serie':'Log at least one set','Duración inválida':'Invalid duration','Rutina vacía':'Empty routine','Sobre de salud inválido':'Invalid health envelope','Sesión de entrenamiento inválida':'Invalid workout session','Perfil dietario inválido':'Invalid dietary profile','El archivo debe contener un array de registros':'The file must contain an array of records','Payload mayor de 8 KB. Exporta el archivo.':'Payload exceeds 8 KB. Export the file.'};
  const t=(es:string,en:string)=>prefs.language==='es'?es:en;
  const n=(count:number,es:[string,string],en:[string,string])=>`${count} ${prefs.language==='es'?(count===1?es[0]:es[1]):(count===1?en[0]:en[1])}`;
  const name=(ref:string)=>{const e=exerciseByRef(ref);return prefs.language==='es'?e.name_es:e.name;};
  const groups:Record<string,[string,string]>={back:['Espalda','Back'],legs:['Piernas','Legs'],glutes:['Glúteos y cadera','Glutes & hips'],chest:['Pecho','Chest'],shoulders:['Hombros','Shoulders'],arms:['Brazos','Arms'],core:['Abdominales','Core'],mobility:['Movilidad','Mobility'],'posterior-chain':['Cadena posterior','Posterior chain']};
  const eqEs:Record<string,string>={Bodyweight:'Peso corporal',Dumbbell:'Mancuerna',Machine:'Máquina',Barbell:'Barra',Cable:'Polea','Resistance Band':'Banda elástica',Cardio:'Cardio','Pull-up Bar':'Barra de dominadas',Wall:'Pared',Towel:'Toalla',Plate:'Disco',Kettlebell:'Pesa rusa',Doorway:'Marco de puerta',Box:'Cajón',Bench:'Banco',Chair:'Silla','Stability Ball':'Balón de estabilidad'};
  const equipmentName=(eq:string)=>prefs.language==='es'?eqEs[eq]??eq:eq;
  const types:Record<string,[string,string]>={weight_reps:['Peso y repeticiones','Weight & reps'],bodyweight_reps:['Repeticiones','Reps'],assisted_bodyweight:['Repeticiones asistidas','Assisted reps'],duration:['Tiempo','Time'],distance_duration:['Distancia y tiempo','Distance & time']};
  const nav=$derived([{href:'/',label:t('Biblioteca','Library'),icon:'book' as IconName},{href:'/rutinas',label:t('Rutinas','Routines'),icon:'clipboard' as IconName},{href:'/entrenar',label:t('Entrenar','Train'),icon:'home' as IconName},{href:'/historial',label:t('Historial y progreso','History & progress'),icon:'chart' as IconName},{href:'/intercambio',label:t('Exportar / importar','Export / import'),icon:'transfer' as IconName},{href:'/ajustes',label:t('Ajustes','Settings'),icon:'settings' as IconName},{href:'/creditos',label:t('Créditos','Credits'),icon:'heart' as IconName}]);
  const path=$derived(page==='library'?'/':page==='detail'?'/biblioteca/'+slug:page==='routines'?'/rutinas':page==='train'?'/entrenar':page==='history'?'/historial':page==='exchange'?'/intercambio':page==='settings'?'/ajustes':'/creditos');
  const filtered=$derived(searchExercises(query,muscle,equipment,type));
  const current=$derived(active?exerciseByRef(active.exercises[active.index].ref):null);
  const points=$derived(progress(sessions,progressRef));
  const weekly=$derived(weeklyVolume(sessions));
  const rest=$derived(active?Math.max(0,Math.ceil((active.restUntil-clock)/1000)):0);
  const chart=$derived(points.map((p,i)=>`${20+i*560/Math.max(1,points.length-1)},${160-p.volume/Math.max(1,...points.map(p=>p.volume))*130}`).join(' '));
  onMount(()=>{const route=location.pathname.split('/').filter(Boolean);const routes:Record<string,string>={'':'library',rutinas:'routines',entrenar:'train',historial:'history',intercambio:'exchange',ajustes:'settings',creditos:'credits'};if(route[0]==='biblioteca'&&route[1]){page='detail';slug=decodeURIComponent(route[1]);}else page=routes[route[0]??'']??page;run(async()=>{
    await initializeLocalStorage();prefs=await readLocal('preferences',{...prefs,subject:`subj_${ulid()}`});await saveLocal('preferences',$state.snapshot(prefs));
    routines=await readLocal('routine',structuredClone(starterRoutines));sessions=await readLocal('workout-session',[]);if(sessions[0])progressRef=sessions[0].data.exercises[0].ref;active=await readLocal('active-session',null);profile=await readLocal('dietary-profile',null);if(active)fillTargets(active);ready=true;
  });const timer=setInterval(()=>clock=Date.now(),1000);return ()=>clearInterval(timer);});
  $effect(()=>{if(!ready||typeof document==='undefined')return;document.documentElement.lang=prefs.language;if(prefs.theme==='system')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=prefs.theme;try{localStorage.setItem('swal-theme',prefs.theme);}catch{}});
  async function run(fn:()=>Promise<void>){if(busy)return;busy=true;error='';message='';try{await fn();}catch(e){const raw=e instanceof Error?e.message:String(e);error=prefs.language==='en'?(englishErrors[raw]??raw):raw;}finally{busy=false;}}
  function fillTargets(s:ActiveSession){const item=s.routine.exercises[s.index];reps=item.reps;weight=Number(kgToDisplay(item.weightKg,prefs.units).toFixed(2));duration=item.durationS;distance=item.distanceM;}
  async function begin(r:Routine){if(active)throw Error(t('Ya tienes una sesión activa. Continúa en Entrenar.','You have an active session. Continue in Train.'));const next=startSession($state.snapshot(r),prefs.bodyKg);await saveLocal('active-session',$state.snapshot(next));active=next;location.href='/entrenar';}
  async function addSet(){if(!active||!current)return;const s=['duration','distance_duration'].includes(current.exerciseType)?{durationS:duration,...(current.exerciseType==='distance_duration'?{distanceM:distance}:{})}:{reps,...(current.exerciseType==='weight_reps'?{weightKg:displayToKg(weight,prefs.units)}:{})};const next=logSet($state.snapshot(active),s);await saveLocal('active-session',$state.snapshot(next));active=next;}
  async function changeExercise(index:number){if(!active)return;const next={...$state.snapshot(active),index,restUntil:0};await saveLocal('active-session',$state.snapshot(next));active=next;fillTargets(next);}
  async function finish(){if(!active)return;const record=finishSession($state.snapshot(active),prefs.subject,new Date().toISOString(),notes,effort);const next=[record,...sessions.filter(s=>s.id!==record.id)];await saveLocal('workout-session',$state.snapshot(next));await saveLocal('active-session',null);sessions=next;active=null;location.href='/historial';}
  async function saveRoutine(){if(!editing||!editing.name.trim()||!editing.exercises.length)throw Error(t('Añade un nombre y ejercicios.','Add a name and exercises.'));for(const x of editing.exercises){if(!Number.isInteger(x.sets)||x.sets<1||x.sets>100||!Number.isInteger(x.reps)||x.reps<1||![x.weightKg,x.durationS,x.distanceM,x.restS].every(Number.isFinite)||x.weightKg<0||x.durationS<=0||x.distanceM<=0||x.restS<0)throw Error(t('Revisa los objetivos de la rutina.','Check routine targets.'));}const next=[...routines.filter(r=>r.id!==editing!.id),$state.snapshot(editing)];await saveLocal('routine',$state.snapshot(next));routines=next;editing=null;}
  function move(index:number,direction:number){if(!editing)return;const list=[...editing.exercises];[list[index],list[index+direction]]=[list[index+direction],list[index]];editing={...editing,exercises:list};}
  function download(records:Workout[]){const blob=new Blob([toHealthFile($state.snapshot(records))],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`biohuman-${new Date().toISOString().slice(0,10)}.swalhealth.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function importFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5_000_000)throw Error(t('Archivo mayor de 5 MB.','File exceeds 5 MB.'));importText=await file.text();const records=parseHealthFile(importText);const expired=records.some(r=>r.schema==='swal.health/v1/dietary-profile'&&Date.parse(r.data.expiresAt)<=Date.now());if(expired)throw Error(t('Perfil dietario caducado.','Dietary profile expired.'));const workouts=records.filter((r):r is Workout=>r.schema==='swal.health/v1/workout-session');const foreign=workouts.some(w=>w.subject!==prefs.subject);if(foreign){if(sessions.length||active)throw Error(t('El sujeto difiere. Usa un dispositivo sin sesiones para restaurar esta copia.','Subject differs. Use a device without sessions to restore this backup.'));if(new Set(workouts.map(w=>w.subject)).size!==1)throw Error(t('El archivo contiene varios sujetos.','The file contains multiple subjects.'));pendingRestore=workouts;pendingProfile=records.find((r):r is DietaryProfile=>r.schema==='swal.health/v1/dietary-profile')??null;return;}const importedProfile=records.find((r):r is DietaryProfile=>r.schema==='swal.health/v1/dietary-profile');if(importedProfile&&Date.parse(importedProfile.data.expiresAt)<=Date.now())throw Error(t('Perfil dietario caducado.','Dietary profile expired.'));const map=new Map(sessions.map(s=>[s.id,s]));workouts.forEach(w=>map.set(w.id,w));const next=[...map.values()].sort((a,b)=>b.data.startedAt.localeCompare(a.data.startedAt));await saveLocal('workout-session',$state.snapshot(next));sessions=next;pendingProfile=importedProfile??null;message=t(`${workouts.length} ${workouts.length===1?'sesión importada':'sesiones importadas'} (sin duplicados).`,`${workouts.length} ${workouts.length===1?'session':'sessions'} imported (deduplicated).`);}
  async function savePreferences(){if(!Number.isFinite(prefs.bodyKg)||prefs.bodyKg<20||prefs.bodyKg>400)throw Error(t('Masa corporal: 20–400 kg.','Body mass: 20–400 kg.'));await saveLocal('preferences',$state.snapshot(prefs));message=t('Ajustes guardados.','Settings saved.');}
</script>
<AppShell currentPath={page==='detail'?'/':path} {nav} menuLabel={t('Menú','Menu')} brandName="BioHuman" tickerMessage={t('En este dispositivo','On this device')}>
  {#if error}<p class="error" role="alert">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}
  {#if !ready}<div class="panel" aria-busy="true">{t('Abriendo tu cuaderno de entrenamiento…','Opening your training journal…')}{#if error}<Button onclick={()=>location.reload()}>{t('Reintentar','Retry')}</Button>{/if}</div>
  {:else if page==='library'}
    <header class="intro"><p class="eyebrow">BIOHUMAN</p><div class="row between"><h1>{t('Movimiento, a tu ritmo.','Movement, at your pace.')}</h1><Badge variant="neutral">{n(302,['ejercicio','ejercicios'],['exercise','exercises'])}</Badge></div><p class="muted">{t('Explora ejercicios, construye tu rutina y lleva un registro de cada avance. Todo queda en tu dispositivo.','Explore exercises, build your routine and track every step forward. Everything stays on your device.')}</p></header>
    {#if active}<div class="panel row between"><span>{t('Tienes una sesión en curso','You have an active session')} · {active.routine.name}</span><a href="/entrenar">{t('Continuar','Continue')} →</a></div>{/if}
    <section class="filters panel" aria-label={t('Filtros','Filters')}><label>{t('Buscar ejercicios','Search exercises')}<input type="search" bind:value={query} oninput={()=>visible=24} placeholder={t('Sentadilla, press, espalda…','Squat, press, back…')}/></label><label>{t('Grupo muscular','Muscle group')}<select bind:value={muscle} onchange={()=>visible=24}><option value="">{t('Todos los músculos','All muscles')}</option>{#each Object.entries(groups) as [key,labels]}<option value={key}>{t(...labels)}</option>{/each}</select></label><label>{t('Equipo','Equipment')}<select bind:value={equipment} onchange={()=>visible=24}><option value="">{t('Todo el equipo','All equipment')}</option>{#each [...new Set(exercises.map(e=>e.equipment))].sort() as eq}<option value={eq}>{equipmentName(eq)}</option>{/each}</select></label><label>{t('Tipo','Type')}<select bind:value={type} onchange={()=>visible=24}><option value="">{t('Todos los tipos','All types')}</option>{#each Object.entries(types) as [key,labels]}<option value={key}>{t(...labels)}</option>{/each}</select></label></section>
    <div class="row between result"><h2>{t('Biblioteca de ejercicios','Exercise library')}</h2><small class="muted" aria-live="polite">{n(filtered.length,['resultado','resultados'],['result','results'])}</small></div>
    <div class="exercise-grid">{#each filtered.slice(0,visible) as e}<a class="exercise-card panel" href={`/biblioteca/${e.slug}`}><div class="silhouette"><ExerciseArt slug={e.slug}/></div><div class="card-copy"><small class="muted">{t(...groups[e.muscleGroup])} / {equipmentName(e.equipment)}</small><h3>{prefs.language==='es'?e.name_es:e.name}</h3><span class="muted">{t('Ver ejercicio','View exercise')} <span aria-hidden="true">↗</span></span></div></a>{/each}</div>
    {#if !filtered.length}<p class="panel">{t('No hay resultados. Prueba otro término o elimina filtros.','No results. Try another term or clear filters.')}</p>{/if}{#if filtered.length>visible}<div class="more"><Button variant="secondary" onclick={()=>visible+=24}>{t('Mostrar más','Show more')}</Button></div>{/if}
  {:else if page==='detail'}
    {@const e=exercises.find(e=>e.slug===slug)}
    {#if e}<a href="/">← {t('Biblioteca','Library')}</a><div class="detail"><div class="panel"><ExerciseArt slug={e.slug} animate/></div><section class="stack"><div><p class="eyebrow">{t(...groups[e.muscleGroup])}</p><h1>{name(e.id)}</h1><p class="muted">{prefs.language==='es'?e.name:e.name_es}</p></div><div class="panel stack"><div><small class="muted">{t('Músculo principal','Primary muscle')}</small><p>{e.primaryMuscle}</p></div><div><small class="muted">{t('Músculos secundarios','Secondary muscles')}</small><p>{e.secondaryMuscles.join(', ')||'—'}</p></div><div><small class="muted">{t('Equipo / tipo','Equipment / type')}</small><p>{equipmentName(e.equipment)} · {t(...types[e.exerciseType])}</p></div><small class="muted">{t('Dificultad estimada','Estimated difficulty')}: {e.difficulty==='beginner'?t('Principiante','Beginner'):e.difficulty==='advanced'?t('Avanzado','Advanced'):t('Intermedio','Intermediate')} · {t('heurística por equipo y modalidad','equipment and modality heuristic')}</small></div><Button disabled={busy||!!active} onclick={()=>run(()=>begin({id:`quick-${e.slug}`,name:name(e.id),exercises:[target(e.slug)]}))}>{t('Entrenar este ejercicio','Train this exercise')}</Button><small class="muted">Art © Bryl Lim, based on Everkinetic, <a href="/creditos">CC BY-SA 4.0</a></small></section></div>{/if}
  {:else if page==='routines'}
    <header class="intro row between"><div><p class="eyebrow">{t('TU PLAN','YOUR PLAN')}</p><h1>{t('Rutinas','Routines')}</h1><p class="muted">{t('Una estructura para volver, una serie a la vez.','A structure to return to, one set at a time.')}</p></div><Button onclick={()=>editing={id:ulid(),name:'',exercises:[]}}>{t('Crear rutina','Create routine')}</Button></header>
    {#if editing}<section class="panel stack"><h2>{t('Editar rutina','Edit routine')}</h2><label>{t('Nombre de la rutina','Routine name')}<input bind:value={editing.name}/></label><div class="grid"><label>{t('Buscar en catálogo','Search catalog')}<input bind:value={routineQuery}/></label><label>{t('Añadir ejercicio','Add exercise')}<select bind:value={addRef}>{#each searchExercises(routineQuery) as e}<option value={e.id}>{name(e.id)}</option>{/each}</select></label></div><Button variant="secondary" onclick={()=>{if(editing)editing.exercises=[...editing.exercises,target(exerciseByRef(addRef).slug)];}}>{t('Añadir','Add')}</Button>
      {#each editing.exercises as item,i}<div class="routine-item stack"><div class="row between"><strong>{i+1}. {name(item.ref)}</strong><div class="row"><button aria-label={t('Subir','Move up')} disabled={i===0} onclick={()=>move(i,-1)}>↑</button><button aria-label={t('Bajar','Move down')} disabled={i===editing.exercises.length-1} onclick={()=>move(i,1)}>↓</button><button onclick={()=>{if(editing)editing.exercises=editing.exercises.filter((_,n)=>n!==i);}}>{t('Quitar','Remove')}</button></div></div><div class="targets"><label>{t('Series','Sets')}<input type="number" min="1" max="100" bind:value={item.sets}/></label><label>{t('Repeticiones','Reps')}<input type="number" min="1" bind:value={item.reps}/></label><label>{t('Peso objetivo','Target weight')} ({prefs.units})<input type="number" min="0" step=".1" value={Number(kgToDisplay(item.weightKg,prefs.units).toFixed(2))} oninput={e=>item.weightKg=displayToKg(Number(e.currentTarget.value),prefs.units)}/></label><label>{t('Duración (s)','Duration (s)')}<input type="number" min="1" bind:value={item.durationS}/></label><label>{t('Distancia (m)','Distance (m)')}<input type="number" min="1" bind:value={item.distanceM}/></label><label>{t('Descanso (s)','Rest (s)')}<input type="number" min="0" bind:value={item.restS}/></label></div></div>{/each}<div class="row"><Button disabled={busy} onclick={()=>run(saveRoutine)}>{t('Guardar rutina','Save routine')}</Button><Button variant="ghost" onclick={()=>editing=null}>{t('Cancelar','Cancel')}</Button></div></section>{/if}
    <div class="grid">{#each routines as r}<article class="panel stack"><div><Badge variant="neutral">{n(r.exercises.length,['ejercicio','ejercicios'],['exercise','exercises'])}</Badge><h2 style="margin-top:1rem">{r.name}</h2></div><ol class="routine-list">{#each r.exercises as item}<li>{name(item.ref)} <small class="muted">{item.sets} × {['duration','distance_duration'].includes(exerciseByRef(item.ref).exerciseType)?`${item.durationS} s`:item.reps}</small></li>{/each}</ol><div class="row"><Button disabled={busy||!!active} onclick={()=>run(()=>begin(r))}>{t('Empezar','Start')}</Button><Button variant="secondary" onclick={()=>editing=structuredClone($state.snapshot(r))}>{t('Editar','Edit')}</Button></div></article>{/each}</div>
  {:else if page==='train'}
    <header class="intro"><p class="eyebrow">{t('UNA SERIE A LA VEZ','ONE SET AT A TIME')}</p><h1>{t('Entrenar','Train')}</h1></header>
    {#if active&&current}<div class="runner"><section class="panel stack"><div class="row between"><Badge variant="neutral">{active.index+1} / {active.exercises.length}</Badge><small>{active.routine.name}</small></div><ExerciseArt slug={current.slug} animate/><h2>{name(current.id)}</h2><small class="muted">{t('Objetivo','Target')}: {n(active.routine.exercises[active.index].sets,['serie','series'],['set','sets'])} · {active.routine.exercises[active.index].reps} {t('reps','reps')} / {active.routine.exercises[active.index].durationS} s</small><label>{t('Ejercicio actual','Current exercise')}<select value={active.index} onchange={(e)=>run(()=>changeExercise(Number(e.currentTarget.value)))}>{#each active.exercises as e,i}<option value={i}>{i+1}. {name(e.ref)} ({e.sets.length})</option>{/each}</select></label><div class="row"><Button variant="secondary" disabled={active.index===0||busy} onclick={()=>run(()=>changeExercise(active!.index-1))}>{t('Anterior','Previous')}</Button><Button variant="secondary" disabled={active.index===active.exercises.length-1||busy} onclick={()=>run(()=>changeExercise(active!.index+1))}>{t('Siguiente','Next')}</Button></div></section>
    <section class="stack"><form class="panel stack" onsubmit={(e)=>{e.preventDefault();run(addSet);}}><h2>{t('Registrar serie','Log set')}</h2><div class="grid">{#if ['weight_reps','bodyweight_reps','assisted_bodyweight'].includes(current.exerciseType)}<label>{t('Repeticiones','Reps')}<input type="number" min="1" step="1" required bind:value={reps}/></label>{/if}{#if current.exerciseType==='weight_reps'}<label>{t('Peso','Weight')} ({prefs.units})<input type="number" min="0" step=".1" required bind:value={weight}/></label>{/if}{#if ['duration','distance_duration'].includes(current.exerciseType)}<label>{t('Tiempo (s)','Time (s)')}<input type="number" min="1" required bind:value={duration}/></label>{/if}{#if current.exerciseType==='distance_duration'}<label>{t('Distancia (m)','Distance (m)')}<input type="number" min="1" required bind:value={distance}/></label>{/if}</div><Button type="submit" disabled={busy}>{t('Registrar serie','Log set')}</Button><small class="muted">{t('Se guarda después de cada serie. Puedes cerrar y continuar.','Saved after every set. You can close and resume.')}</small></form>
    <div class="panel row between" role="timer" aria-label={t('Descanso','Rest')}><div><small class="muted">{t('Descanso','Rest')}</small><div class="timer number">{Math.floor(rest/60)}:{String(rest%60).padStart(2,'0')}</div></div><Button variant="ghost" disabled={!rest||busy} onclick={()=>run(async()=>{if(active){const next={...$state.snapshot(active),restUntil:0};await saveLocal('active-session',$state.snapshot(next));active=next;}})}>{t('Saltar descanso','Skip rest')}</Button></div>
    <div class="panel"><h2>{t('Series registradas','Logged sets')}</h2>{#if !active.exercises[active.index].sets.length}<p class="muted">{t('Tu primera serie empieza aquí.','Your first set starts here.')}</p>{/if}<ol>{#each active.exercises[active.index].sets as s}<li class="set-line">{s.reps?`${s.reps} ${t('reps','reps')}`:''} {s.weightKg!==undefined?`· ${kgToDisplay(s.weightKg,prefs.units).toFixed(1)} ${prefs.units}`:''} {s.durationS?`· ${s.durationS} s`:''} {s.distanceM?`· ${s.distanceM} m`:''}</li>{/each}</ol></div>
    <div class="panel stack"><label>{t('Notas','Notes')}<textarea bind:value={notes}></textarea></label><label>{t('Esfuerzo percibido (1–10)','Perceived effort (1–10)')}<input type="number" min="1" max="10" bind:value={effort}/></label><Button disabled={busy||!active.exercises.some(e=>e.sets.length)} onclick={()=>run(finish)}>{t('Finalizar entrenamiento','Finish workout')}</Button><small class="muted">{t('Se guardarán los ejercicios con series registradas.','Exercises with logged sets will be saved.')}</small></div></section></div>
    {:else}<div class="panel stack"><h2>{t('Elige tu próxima sesión','Choose your next session')}</h2><p class="muted">{t('Empieza desde una rutina o desde cualquier ejercicio de la biblioteca.','Start from a routine or any exercise in the library.')}</p><a href="/rutinas">{t('Ver rutinas','View routines')} →</a></div>{/if}
  {:else if page==='history'}
    <header class="intro"><p class="eyebrow">{t('TU CUADERNO','YOUR JOURNAL')}</p><h1>{t('Historial y progreso','History & progress')}</h1><p class="muted">{n(sessions.length,['sesión guardada','sesiones guardadas'],['saved session','saved sessions'])}</p></header>
    {#if !sessions.length}<div class="panel stack"><h2>{t('Cada comienzo cuenta.','Every beginning counts.')}</h2><p class="muted">{t('Al finalizar tu primera sesión, verás aquí tu progreso.','Finish your first session to see your progress here.')}</p><a href="/rutinas">{t('Empezar una rutina','Start a routine')} →</a></div>{:else}<div class="panel stack"><h2>{t('Progreso por ejercicio','Exercise progress')}</h2><label>{t('Ejercicio','Exercise')}<select bind:value={progressRef}>{#each exercises.filter(e=>sessions.some(s=>s.data.exercises.some(x=>x.ref===e.id))) as e}<option value={e.id}>{name(e.id)}</option>{/each}</select></label>{#if points.length}<div class="grid"><div><small class="muted">{t('Mejor peso registrado','Best logged weight')}</small><h2 class="number">{kgToDisplay(Math.max(...points.map(p=>p.best)),prefs.units).toFixed(1)} {prefs.units}</h2></div><div><small class="muted">{t('Máximo por serie: reps / s / m','Best set: reps / s / m')}</small><h2 class="number">{Math.max(...points.map(p=>p.bestReps))} / {Math.max(...points.map(p=>p.bestDuration))} / {Math.max(...points.map(p=>p.bestDistance))}</h2></div></div><svg viewBox="0 0 600 190" class="chart" role="img" aria-label={t('Volumen por sesión en kg × repeticiones','Session volume in kg × reps')}><path d="M20 20V160H580" fill="none" stroke="currentColor" opacity=".2"/><polyline points={chart} fill="none" stroke="currentColor" stroke-width="2"/>{#each points as p,i}<circle cx={20+i*560/Math.max(1,points.length-1)} cy={160-p.volume/Math.max(1,...points.map(p=>p.volume))*130} r="4" fill="currentColor"><title>{p.date.slice(0,10)}: {p.volume} kg × reps</title></circle>{/each}</svg><div class="row between muted"><small>{points[0].date.slice(0,10)}</small><small>{t('Volumen (kg × reps)','Volume (kg × reps)')}</small><small>{points.at(-1)?.date.slice(0,10)}</small></div>{:else}<p class="muted">{t('Selecciona un ejercicio registrado.','Select a logged exercise.')}</p>{/if}</div>
    <section class="panel" style="margin-top:1rem"><h2>{t('Volumen semanal','Weekly volume')}</h2>{#each weekly as w}<div class="row between set-line"><span>{t('Semana del','Week of')} {w.date}</span><strong class="number">{kgToDisplay(w.volume,prefs.units).toFixed(0)} {prefs.units} × reps</strong></div>{/each}<small class="muted">{t('Solo carga externa; el peso corporal no se suma al volumen.','External load only; bodyweight is not included in volume.')}</small></section>
    <div class="stack" style="margin-top:1rem">{#each sessions as s}<article class="panel stack"><div class="row between"><h2>{new Date(s.data.startedAt).toLocaleString(prefs.language)}</h2><Badge variant="neutral">{n(s.data.exercises.reduce((v,e)=>v+e.sets.length,0),['serie','series'],['set','sets'])}</Badge></div><div class="row muted"><span>{Math.round((Date.parse(s.data.endedAt)-Date.parse(s.data.startedAt))/60000)} min</span><span>{kgToDisplay(sessionVolume(s),prefs.units).toFixed(0)} {prefs.units} × reps</span><span>≈ {s.data.energy.kcal} kcal · met-estimate</span></div><ul>{#each s.data.exercises as e}<li>{exercises.some(x=>x.id===e.ref)?name(e.ref):e.ref} · {n(e.sets.length,['serie','series'],['set','sets'])}</li>{/each}</ul>{#if s.data.notes}<p>{s.data.notes}</p>{/if}<div class="row"><Button variant="secondary" onclick={()=>run(async()=>download([s]))}>{t('Exportar sesión','Export session')}</Button><Button variant="ghost" onclick={()=>run(async()=>link=await orionDeepLink([s]))}>{t('Enviar a OrionHealth','Send to OrionHealth')}</Button></div></article>{/each}</div>{/if}
  {:else if page==='exchange'}
    <header class="intro"><p class="eyebrow">SWAL / HEALTH V1</p><h1>{t('Tus datos viajan contigo.','Your data travels with you.')}</h1><p class="muted">{t('Comparte archivos con OrionHealth o importa una copia de tus sesiones. Tú decides qué sale del dispositivo.','Share files with OrionHealth or import a copy of your sessions. You decide what leaves your device.')}</p></header><div class="grid"><section class="panel stack"><h2>{t('Exportar sesiones','Export sessions')}</h2><p class="muted">{n(sessions.length,['sesión','sesiones'],['session','sessions'])} {t('en formato .swalhealth.json','in .swalhealth.json format')}</p><Button disabled={!sessions.length||busy} onclick={()=>run(async()=>download(sessions))}>{t('Descargar archivo','Download file')}</Button><Button variant="secondary" disabled={!sessions.length||busy} onclick={()=>run(async()=>link=await orionDeepLink(sessions))}>{t('Generar enlace OrionHealth','Generate OrionHealth link')}</Button><small class="muted">{t('Los enlaces usan gzip + base64url. Si superan 8 KB, usa el archivo.','Links use gzip + base64url. Above 8 KB, use the file.')}</small></section><section class="panel stack"><h2>{t('Importar archivo','Import file')}</h2><label>{t('Archivo .swalhealth.json','File .swalhealth.json')}<input type="file" accept=".json,.swalhealth.json" disabled={busy} onchange={e=>run(()=>importFile(e))}/></label><small class="muted">{t('Las sesiones se validan y deduplican por ULID; deben pertenecer a tu sujeto local.','Sessions are validated and deduplicated by ULID; they must belong to your local subject.')}</small><small class="number">{prefs.subject}</small></section></div>
    {#if pendingRestore}<section class="panel stack" style="margin-top:1rem"><h2>{t('Restaurar copia de otro dispositivo','Restore backup from another device')}</h2><p>{t('Este dispositivo está vacío. Puedes adoptar el sujeto del archivo para recuperar tus sesiones.','This device is empty. You can adopt the file subject to recover your sessions.')}</p><p class="number">{pendingRestore[0].subject}</p><div class="row"><Button onclick={()=>run(async()=>{if(!pendingRestore)return;const nextPrefs={...$state.snapshot(prefs),subject:pendingRestore[0].subject};await saveLocal('preferences',nextPrefs);await saveLocal('workout-session',$state.snapshot(pendingRestore));prefs=nextPrefs;sessions=pendingRestore;pendingRestore=null;message=t('Copia restaurada.','Backup restored.');})}>{t('Restaurar mis sesiones','Restore my sessions')}</Button><Button variant="ghost" onclick={()=>{pendingRestore=null;pendingProfile=null;}}>{t('Descartar','Discard')}</Button></div></section>{/if}
    {#if pendingProfile}<section class="panel stack" style="margin-top:1rem"><h2>{t('Perfil dietario opcional','Optional dietary profile')}</h2><p>{t('¿Guardar este perfil compartido por OrionHealth en el dispositivo?','Save this profile shared by OrionHealth on this device?')}</p><p>{pendingProfile.data.allergens.join(', ')||t('Sin alérgenos declarados','No declared allergens')} · {pendingProfile.data.diets.join(', ')}</p><div class="row"><Button onclick={()=>run(async()=>{await saveLocal('dietary-profile',$state.snapshot(pendingProfile));profile=pendingProfile;pendingProfile=null;message=t('Perfil guardado con tu consentimiento.','Profile saved with your consent.');})}>{t('Aceptar perfil','Accept profile')}</Button><Button variant="ghost" onclick={()=>pendingProfile=null}>{t('Descartar','Discard')}</Button></div></section>{/if}
    {#if profile}<section class="panel" style="margin-top:1rem"><h2>{t('Perfil dietario guardado','Saved dietary profile')}</h2><p>{profile.data.allergens.join(', ')||'—'} / {profile.data.diets.join(', ')||'—'}</p><p class="muted">{t('Caduca','Expires')}: {new Date(profile.data.expiresAt).toLocaleDateString(prefs.language)} {Date.parse(profile.data.expiresAt)<=clock?t('(caducado)','(expired)'):''}</p><Button variant="ghost" onclick={()=>run(async()=>{await saveLocal('dietary-profile',null);profile=null;})}>{t('Eliminar perfil','Remove profile')}</Button></section>{/if}
  {:else if page==='settings'}
    <header class="intro"><p class="eyebrow">{t('A TU MANERA','YOUR WAY')}</p><h1>{t('Ajustes','Settings')}</h1></header><form class="panel stack settings" onsubmit={e=>{e.preventDefault();run(savePreferences);}}><label>{t('Tema','Theme')}<select bind:value={prefs.theme}><option value="system">{t('Sistema','System')}</option><option value="light">{t('Claro','Light')}</option><option value="dark">{t('Oscuro','Dark')}</option></select></label><label>{t('Unidades de peso','Weight units')}<select bind:value={prefs.units}><option value="kg">kg</option><option value="lb">lb</option></select></label><label>{t('Idioma','Language')}<select bind:value={prefs.language}><option value="es">Español</option><option value="en">English</option></select></label><label>{t('Masa corporal para estimación MET (kg)','Body mass for MET estimate (kg)')}<input type="number" min="20" max="400" step=".1" bind:value={prefs.bodyKg} required/></label><small class="muted">{t('El formato de intercambio siempre usa kg.','The interchange format always uses kg.')}</small><Button type="submit" disabled={busy}>{t('Guardar ajustes','Save settings')}</Button></form>
  {:else if page==='credits'}
    <header class="intro"><p class="eyebrow">{t('HECHO EN COMUNIDAD','BUILT TOGETHER')}</p><h1>{t('Créditos','Credits')}</h1></header><section class="panel stack"><h2>{t('Ilustraciones de ejercicios','Exercise illustrations')}</h2><p>Art © Bryl Lim, based on Everkinetic, CC BY-SA 4.0</p><p><a href="https://github.com/bryllim/workout-guide">@bryllim/workout-guide 1.0.0</a> · aac5992 · {n(302,['ejercicio','ejercicios'],['exercise','exercises'])} / 906 SVG</p><p>{t('Modificaciones: minificación SVGO y sustitución de fill="#fff" por fill="currentColor" para adaptar las siluetas al tema. El arte modificado conserva CC BY-SA 4.0.','Changes: SVGO minification and replacement of fill="#fff" with fill="currentColor" to adapt silhouettes to the theme. Modified artwork retains CC BY-SA 4.0.')}</p><div class="row"><a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a><a href="/exercises/ATTRIBUTION.md">{t('Atribución completa','Full attribution')}</a><a href="/exercises/LICENSE-ASSETS">{t('Licencia de arte','Artwork license')}</a><a href="/exercises/LICENSE-MIT">MIT</a></div><h2>{t('Energía estimada','Estimated energy')}</h2><p>{t('Valores MET del Adult Compendium 2024: resistencia 3.5; peso corporal 3.0; estiramiento 2.3. Media de ejercicios por duración total de sesión, incluidos descansos. Usa la masa de Ajustes (inicial 70 kg).','MET values from the 2024 Adult Compendium: resistance 3.5; bodyweight 3.0; stretching 2.3. Exercise average over total session duration, including rests. Uses Settings mass (initially 70 kg).')}</p><a href="https://pacompendium.com/adult-compendium/">2024 Adult Compendium of Physical Activities</a><p class="muted">{t('Dificultad estimada por heurística; no hay instrucciones técnicas verificadas en el catálogo.','Difficulty is estimated heuristically; the catalog has no verified technique instructions.')}</p><h2>{t('Interfaz','Interface')}</h2><p>@swal/ui · Bone Warm Minimalist · {t('Shell de Fize','Fize shell')} · {t('Iconos de trazos basados en Lucide (ISC)','Line icons based on Lucide (ISC)')}</p></section>
  {/if}
  {#if link}<section class="panel stack" style="margin-top:1rem"><h2>{t('Enlace para OrionHealth','OrionHealth link')}</h2><a href={link}>{t('Abrir OrionHealth','Open OrionHealth')} →</a><label>{t('Copiar enlace','Copy link')}<textarea readonly value={link}></textarea></label><Button variant="ghost" onclick={()=>link=''}>{t('Cerrar','Close')}</Button></section>{/if}
</AppShell>
<style>
.filters{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:.8rem;margin:1.25rem 0}.result{margin:2rem 0 1rem}.result h2{margin:0}.exercise-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:1rem}.exercise-card{text-decoration:none;padding:0;overflow:hidden;transition:transform 150ms}.exercise-card:hover{transform:translateY(-3px);border-color:var(--swal-border-strong)}.silhouette{padding:1rem 2rem;border-bottom:1px solid var(--swal-border);background:var(--swal-hover)}.card-copy{padding:1rem}.card-copy h3{margin:.55rem 0 1rem}.card-copy span{font-size:.75rem}.more{display:flex;justify-content:center;margin:2rem}.detail{display:grid;grid-template-columns:1fr 1fr;gap:2rem;margin-top:2rem}.runner{display:grid;grid-template-columns:minmax(220px,1fr) minmax(280px,1.3fr);gap:1.5rem}.timer{font-size:2.5rem}.targets{display:grid;grid-template-columns:repeat(3,1fr);gap:.75rem}.routine-item{border-top:1px solid var(--swal-border);padding-top:1rem}.routine-list{padding-left:1.2rem;margin:0;line-height:1.9;flex:1}.set-line{padding:.6rem 0;border-bottom:1px solid var(--swal-border)}.chart{width:100%;max-height:240px}.settings{max-width:600px}ul{line-height:1.9}@media(max-width:1000px){.filters{grid-template-columns:1fr 1fr}}@media(max-width:650px){.filters,.detail,.runner{grid-template-columns:1fr}.exercise-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:.6rem}.exercise-card .silhouette{padding:.5rem}.card-copy{padding:.75rem}.targets{grid-template-columns:repeat(2,minmax(0,1fr))}.card-copy small{font-size:.65rem}.card-copy h3{font-size:.9rem}.detail{gap:1rem}}
</style>
